select jsonb_build_object('server_now',clock_timestamp(),'accounts',(select count(*)from auth.users),'profiles',(select count(*)from profiles),'objects',(select count(*)from storage.objects where bucket_id='profile-photos'),'matches',(select count(*)from matches),'messages',(select count(*)from messages),'windows',(select count(*)from spot_private.discovery_windows),'allocations',(select count(*)from spot_private.discovery_allocations),'exposures',(select count(*)from spot_private.discovery_exposures),'fairness',(select count(*)from spot_private.discovery_fairness_buckets),'pair_memory',(select count(*)from spot_private.discovery_pair_memory),'policy',(select jsonb_agg(to_jsonb(p))from spot_private.discovery_policy p),'control',(select to_jsonb(c)from spot_private.soma_v2_control c),'photo_control',(select jsonb_build_object('phase',phase,'epoch',epoch,'cleanup',execute_enabled,'scheduler',scheduler_enabled)from spot_private.photo_cutover_control),'migration038',to_regprocedure('spot_private.dd_clock_at(timestamptz)'),'retention_paused',(select paused from spot_private.retention_control)) evidence;
